const HeroChat: React.FC = () => {
    const [messages, setMessages] = useState<{role: 'ai' | 'user', text: string}[]>([
        { role: 'ai', text: 'Hola, ¿te gustaría agendar una cita para aumentar tus ventas hoy?' }
